#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 1000000007;

int readInt() {
    int x = 0, f = 1;
    char c = getchar();
    while (c < '0' || c > '9') {
        if (c == '-') f = -1;
        c = getchar();
    }
    while (c >= '0' && c <= '9') {
        x = x * 10 + c - '0';
        c = getchar();
    }
    return x * f;
}

ll modPow(ll base, ll exp) {
    ll res = 1;
    base %= MOD;
    while (exp) {
        if (exp & 1) res = res * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return res;
}

ll modInv(ll x) {
    return modPow(x, MOD - 2);
}

void add(int& a, int b) {
    a = (a + b) % MOD;
    if (a < 0) a += MOD;
}

void sub(int& a, int b) {
    a = (a - b + MOD) % MOD;
}

void fwht(vector<int>& a, int invert) {
    int n = a.size();
    for (int len = 2; len <= n; len <<= 1) {
        for (int i = 0; i < n; i += len) {
            for (int j = 0; j < len / 2; j++) {
                int u = a[i + j];
                int v = a[i + j + len / 2];
                if (invert == 1) {
                    a[i + j] = (u + v) % MOD;
                    a[i + j + len / 2] = v;
                } else {
                    a[i + j] = (u - v + MOD) % MOD;
                    a[i + j + len / 2] = v;
                }
            }
        }
    }
}

int main() {
    int n = readInt();
    vector<vector<int>> p(6, vector<int>(6));

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            p[i][j] = (int)((ll)readInt() * modInv(100) % MOD);
        }
    }

    for (int i = n; i < 6; i++) {
        p[i][i] = 1;
    }

    vector<int> id(64, -1);
    int cnt = 0;
    for (int i = 0; i < 64; i++) {
        if (__builtin_popcount(i) == 3) {
            id[i] = cnt++;
        }
    }

    vector<int> X(1 << 18, 0), Y(1 << 18, 0);

    for (int mask = 0; mask < (1 << 18); mask++) {
        int m1 = mask & 63;
        int m2 = (mask >> 6) & 63;
        int m3 = (mask >> 12) & 63;

        ll prob = 1;
        for (int j = 0; j < 6; j++) {
            if (m1 >> j & 1) prob = prob * p[0][j] % MOD;
            else prob = prob * (MOD + 1 - p[0][j]) % MOD;
        }
        for (int j = 0; j < 6; j++) {
            if (m2 >> j & 1) prob = prob * p[1][j] % MOD;
            else prob = prob * (MOD + 1 - p[1][j]) % MOD;
        }
        for (int j = 0; j < 6; j++) {
            if (m3 >> j & 1) prob = prob * p[2][j] % MOD;
            else prob = prob * (MOD + 1 - p[2][j]) % MOD;
        }

        int combined = 0;
        for (int a = 0; a < 6; a++) {
            if (m1 >> a & 1) {
                for (int b = 0; b < 6; b++) {
                    if (a == b) continue;
                    if (m2 >> b & 1) {
                        for (int c = 0; c < 6; c++) {
                            if (a == c || b == c) continue;
                            if (m3 >> c & 1) {
                                int nm = (1 << a) | (1 << b) | (1 << c);
                                combined |= 1 << id[nm];
                            }
                        }
                    }
                }
            }
        }
        add(X[combined], (int)prob);
    }

    for (int mask = 0; mask < (1 << 18); mask++) {
        int m1 = mask & 63;
        int m2 = (mask >> 6) & 63;
        int m3 = (mask >> 12) & 63;

        ll prob = 1;
        for (int j = 0; j < 6; j++) {
            if (m1 >> j & 1) prob = prob * p[3][j] % MOD;
            else prob = prob * (MOD + 1 - p[3][j]) % MOD;
        }
        for (int j = 0; j < 6; j++) {
            if (m2 >> j & 1) prob = prob * p[4][j] % MOD;
            else prob = prob * (MOD + 1 - p[4][j]) % MOD;
        }
        for (int j = 0; j < 6; j++) {
            if (m3 >> j & 1) prob = prob * p[5][j] % MOD;
            else prob = prob * (MOD + 1 - p[5][j]) % MOD;
        }

        int combined = 0;
        for (int a = 0; a < 6; a++) {
            if (m1 >> a & 1) {
                for (int b = 0; b < 6; b++) {
                    if (a == b) continue;
                    if (m2 >> b & 1) {
                        for (int c = 0; c < 6; c++) {
                            if (a == c || b == c) continue;
                            if (m3 >> c & 1) {
                                int nm = (1 << a) | (1 << b) | (1 << c);
                                nm ^= 63;
                                combined |= 1 << id[nm];
                            }
                        }
                    }
                }
            }
        }
        add(Y[combined], (int)prob);
    }

    fwht(X, 1);
    fwht(Y, 1);

    for (int i = 0; i < (1 << 18); i++) {
        X[i] = (int)((ll)X[i] * Y[i] % MOD);
    }

    fwht(X, -1);

    int result = 0;
    for (int i = 1; i < (1 << 18); i++) {
        add(result, X[i]);
    }

    printf("%d\n", result);
    return 0;
}
